insert into public.observations (region_code, indicator_id, dataset_id, period_label, year, value, source_id, source_table, source_page, date_pulled, archive_url, break_before, note) values ('NL', 'cpi_inflation', 'cpi_2012_fy', '2024-25', 2025, 3.99, 'mospi-esankhyiki-cpi-2012', 'MoSPI eSankhyiki CPI API getCPIIndex (base_year=2012, series=Current, sector_code=3 combined), subgroup General-Overall, monthly index', 'api (all pages)', '2026-10-17', null, false, 'Calculated by Tathya: mean of the 12 monthly CPI General Index values (base 2012=100, rural+urban) for April 2024 to March 2025, divided by the mean for April 2023 to March 2024, minus 1 (per cent; MoSPI''s method for annual inflation). Means 193.03 and 185.62. State label in API: Nagaland');
